#include <stdio.h>
#include <math.h>

// Function to compute sum of digits of n in base b
int digit_sum(int n, int b) {
    int sum = 0;
    while (n > 0) {
        sum += n % b;
        n /= b;
    }
    return sum;
}

int main() {
    int n, s;
    scanf("%d %d", &n, &s);

    // Special case: n == s => base can be n+1 or larger, smallest is b = n+1
    if (n == s) {
        printf("%d\n", n + 1);
        return 0;
    }

    int ans = -1;

    // Check small bases up to sqrt(n)
    int limit = (int)sqrt(n) + 1;
    for (int b = 2; b <= limit; b++) {
        if (digit_sum(n, b) == s) {
            printf("%d\n", b);
            return 0;
        }
    }

    // Check large bases: n = a*b + c, a + c = s, c < b
    // Then a*b + c = n, a + c = s => a*(b-1) = n - s
    // So b-1 must divide n-s, and b > sqrt(n)
    for (int a = 1; a <= limit; a++) {
        // a = d1 (first digit), b-1 = (n - s) / a
        if ((n - s) % a == 0) {
            int b = (n - s) / a + 1;
            if (b > limit) { // ensure this is a "large base" case
                int c = n - a * b;
                if (c >= 0 && c < b && a + c == s) {
                    if (ans == -1 || b < ans)
                        ans = b;
                }
            }
        }
    }

    printf("%d\n", ans);
    return 0;
}

