typedef long long ll;

static ll digit_sum(ll b, ll n) {
    ll sum = 0;
    while (n > 0) {
        sum += n % b;
        n /= b;
    }
    return sum;
}

int main(void) {
    ll n, s;
    if (scanf("%lld %lld", &n, &s) != 2) return 0;

    if (n == s) {
        printf("%lld\n", n + 1);
        return 0;
    }

    if (n < s) {
        printf("-1\n");
        return 0;
    }

    ll ans = -1;
    ll limit = (ll)sqrt((double)n);

    for (ll b = 2; b <= limit; b++) {
        if (digit_sum(b, n) == s) {
            ans = b;
            break;
        }
    }

    if (ans != -1) {
        printf("%lld\n", ans);
        return 0;
    }

    for (ll p = limit; p >= 1; p--) {
        ll q = s - p;
        if (q < 0) continue;

        ll denom = p;
        ll numer = n - q;
        if (numer <= 0) continue;
        if (numer % denom != 0) continue;

        ll b = numer / denom;
        if (b <= p) continue;
        if (b >= 2 && digit_sum(b, n) == s) {
            ans = b;
        }
    }

    printf("%lld\n", ans);
    return 0;
}

