public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long s = sc.nextLong();

        System.out.println(solve(n, s));
    }

    static long digitSum(long n, long b) {
        long sum = 0;
        while (n > 0) {
            sum += n % b;
            n /= b;
        }
        return sum;
    }

    static long solve(long n, long s) {
        if (s == 1 && n == 1) return 2; // f(2,1) = 1
        if (s > n) return -1; // digit sum <= n always
        if (s == n) return n + 1; // single digit in base n+1

        // Check small bases 2..sqrt(n)
        long sqrtN = (long) Math.sqrt((double) n) + 2;
        for (long b = 2; b <= sqrtN; b++) {
            if (digitSum(n, b) == s) return b;
        }

        // For b in (sqrtN, n]: n has 2 digits, digit sum = 1 + (n - b) = s => b = n - s + 1
        long b = n - s + 1;
        if (b > sqrtN && b >= 2 && b <= n) {
            if (digitSum(n, b) == s) return b;
        }

        return -1;
    }
}

