public class Main {
    static long n, s;

    static long digitSum(long b, long x) {
        long sum = 0;
        while (x > 0) {
            sum += x % b;
            x /= b;
        }
        return sum;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextLong();
        s = fs.nextLong();

        if (n == s) {
            System.out.println(n + 1);
            return;
        }

        if (n < s) {
            System.out.println(-1);
            return;
        }

        long ans = Long.MAX_VALUE;

        long limit = (long) Math.sqrt(n);
        for (long b = 2; b <= limit; b++) {
            if (digitSum(b, n) == s) {
                ans = Math.min(ans, b);
            }
        }

        // For b > sqrt(n), n in base b has at most 2 digits: n = p*b + q
        // Then f(b, n) = p + q = s
        // So n = p*b + (s - p) => b = (n - s + p) / p
        long diff = n - s;
        for (long p = 1; p * p <= n; p++) {
            if (diff % p != 0) continue;
            long b = diff / p + 1;
            if (b >= 2 && digitSum(b, n) == s) {
                ans = Math.min(ans, b);
            }
        }

        System.out.println(ans == Long.MAX_VALUE ? -1 : ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

import math
import sys

def digit_sum(n, b):
    s = 0
    while n > 0:
        s += n % b
        n //= b
    return s

def solve():
    input_data = sys.stdin.read().split()
    n = int(input_data[0])
    s = int(input_data[1])

    if n == 0:
        # 0 in any base is 0
        print(2 if s == 0 else -1)
        return

    candidates = []

    limit = int(math.isqrt(n)) + 2

    for b in range(2, limit + 1):
        if digit_sum(n, b) == s:
            candidates.append(b)

    # Two-digit case: b = n - s + 1, valid if b > sqrt(n) and 2 <= b <= n
    b_two = n - s + 1
    if b_two >= 2 and b_two > math.isqrt(n) and b_two <= n:
        if digit_sum(n, b_two) == s:
            candidates.append(b_two)

    # Single digit case: b = n+1 (if s == n)
    if s == n and n + 1 >= 2:
        candidates.append(n + 1)

    if candidates:
        print(min(candidates))
    else:
        print(-1)

solve()

