    long long limit = sqrt(n) + 1;
    for (long long b = 2; b <= limit; ++b) {
        if (digitSum(n, b) == s) {
            cout << b;
            return 0;
        }
    }

    // For larger bases (b > sqrt(n)), representation has at most 2 digits
    // n = p*b + q, with p < b, s = p + q
    // => n - s = p*(b - 1)
    // iterate over possible p
    long long best = -1;
    for (long long p = 1; p <= limit; ++p) {
        long long diff = n - s;
        if (diff % p == 0) {
            long long b = diff / p + 1;
            if (b >= 2 && b > p) {
                // Check that p < b and digit sum matches
                long long q = s - p;
                if (q >= 0 && q < b) {
                    if (p * b + q == n) {
                        if (best == -1 || b < best)
                            best = b;
                    }
                }
            }
        }
    }

    cout << best;
    return 0;
}

