using namespace std;

typedef long long ll;

ll digitSum(ll n, ll b) {
    ll s = 0;
    while (n > 0) { s += n % b; n /= b; }
    return s;
}

int main() {
    ll n, s;
    cin >> n >> s;

    if (n == 0) { cout << (s == 0 ? 2 : -1); return 0; }
    if (s == 0) { cout << -1; return 0; }

    ll sqrtn = (ll)sqrt((double)n) + 2;

    ll ans = -1;

    // Check b from 2 to sqrtn
    for (ll b = 2; b <= sqrtn; b++) {
        if (digitSum(n, b) == s) { ans = b; break; }
    }

    if (ans == -1) {
        // b > sqrtn, so n/b < sqrtn, quotient q ranges from 1 to sqrtn
        // For each q, b = (n-s)/q + 1 if (n-s) % q == 0
        // Also need to handle n - s possibly being 0 (s == n means b = n+1)
        set<ll> candidates;
        if (s <= n) {
            ll diff = n - s;
            if (diff == 0) { candidates.insert(n + 1); }
            else {
                for (ll q = 1; q <= sqrtn; q++) {
                    if (diff % q == 0) {
                        ll b = diff / q + 1;
                        if (b > sqrtn && b >= 2) candidates.insert(b);
                    }
                }
            }
        }
        for (ll b : candidates) {
            if (digitSum(n, b) == s) { ans = b; break; }
        }
        if (ans == -1 && !candidates.empty()) {
            // find minimum valid
            for (ll b : candidates) if (digitSum(n, b) == s) { ans = b; break; }
        }
    }

    cout << ans;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

static int64 digit_sum_base(int64 b, int64 n) {
    int64 sum = 0;
    while (n > 0) {
        sum += n % b;
        n /= b;
    }
    return sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, s;
    cin >> n >> s;

    // Special case: n == s
    // In any base b > n, representation is a single digit n, so digit sum is n.
    // Smallest such base is n + 1 (and if n == 1, base 2).
    if (n == s) {
        cout << n + 1 << '\n';
        return 0;
    }

    // If s > n, impossible since digit sum in any base is at most n.
    if (s > n) {
        cout << -1 << '\n';
        return 0;
    }

    int64 ans = (1LL << 62);

    // For b <= sqrt(n), brute force directly.
    for (int64 b = 2; b * b <= n; ++b) {
        if (digit_sum_base(b, n) == s) {
            ans = min(ans, b);
        }
    }

    // For b > sqrt(n), n in base b has at most 2 digits:
    // n = p*b + q, with 0 <= q < b, so digit sum = p + q = s.
    // Hence n - s = p*(b - 1), so for each divisor p of (n - s),
    // candidate base is b = (n - s)/p + 1.
    int64 m = n - s;
    for (int64 p = 1; p * p <= m; ++p) {
        if (m % p != 0) continue;

        // Check divisor p
        {
            int64 b = m / p + 1;
            if (b >= 2 && digit_sum_base(b, n) == s) {
                ans = min(ans, b);
            }
        }

        // Check paired divisor m/p
        int64 q = m / p;
        if (q != p) {
            int64 b = m / q + 1;
            if (b >= 2 && digit_sum_base(b, n) == s) {
                ans = min(ans, b);
            }
        }
    }

    if (ans == (1LL << 62)) cout << -1 << '\n';
    else cout << ans << '\n';

    return 0;
}
